import{_ as a,o as i,c as l,a as t}from"./app.2afc42a8.js";const m=JSON.parse('{"title":"陈民-GIS+爬虫+前端-8年政企经验 个人简历","description":"","frontmatter":{},"headers":[],"relativePath":"about/about-my-resume.md","filePath":"about/about-my-resume.md","lastUpdated":1772097588000}'),o={name:"about/about-my-resume.md"};function r(s,e,n,h,u,b){return i(),l("div",null,e[0]||(e[0]=[t('<h1 id="陈民-gis-爬虫-前端-8年政企经验-个人简历" tabindex="-1">陈民-GIS+爬虫+前端-8年政企经验 个人简历 <a class="header-anchor" href="#陈民-gis-爬虫-前端-8年政企经验-个人简历" aria-label="Permalink to &quot;陈民-GIS+爬虫+前端-8年政企经验 个人简历&quot;">​</a></h1><h2 id="个人信息" tabindex="-1">个人信息 <a class="header-anchor" href="#个人信息" aria-label="Permalink to &quot;个人信息&quot;">​</a></h2><ul><li>姓名：陈民</li><li>性别：男</li><li>出生年月：1993.8</li><li>民族：汉</li><li>专业：计算机应用技术</li><li>求职意向：Web 前端开发(GIS/数据可视化方向)</li><li>电子邮箱：zmx2321@163.com</li><li>联系电话：18329042835</li><li>技术主页： <ul><li>Github：<a href="https://github.com/zmx2321" target="_blank" rel="noreferrer">https://github.com/zmx2321</a></li><li>掘金：<a href="https://juejin.im/user/5d26e83451882554c007b4f0" target="_blank" rel="noreferrer">https://juejin.im/user/5d26e83451882554c007b4f0</a></li><li>技术博客：<a href="https://zmx2321.github.io/vite-blog/" target="_blank" rel="noreferrer">https://zmx2321.github.io/vite-blog/</a></li><li>项目Demo：<a href="https://zmx2321.github.io/vue3-admin-demo" target="_blank" rel="noreferrer">https://zmx2321.github.io/vue3-admin-demo</a></li><li>公众号：zmx 的前端日志</li></ul></li></ul><h2 id="核心优势" tabindex="-1">核心优势 <a class="header-anchor" href="#核心优势" aria-label="Permalink to &quot;核心优势&quot;">​</a></h2><ol><li>8年政企数字化/智慧城市深耕，落地10+GIS/数据可视化核心项目，熟练掌握政务大数据开发规范，入职可独立扛岗、统筹开发，高度匹配杭州本地政企技术需求；</li><li>GIS+前端深度融合，精通Vue全生态+ Openlayer/Mapbox/高德二维开发，掌握Cesium三维技术，实现空间与业务数据全链路可视化开发；</li><li>全流程数据处理能力，熟练掌握Python高级爬虫(瑞数反爬/Webpack逆向/AES/RSA加解密)以及PostGIS/MySQL地理数据库，独立完成合规采集-清洗-地理化存储-可视化完整数据闭环；</li><li>全栈开发+ AI提效，掌握Java若依框架，可完成前端+数据采集+ GIS存储+后端全流程开发，AI工具融入开发全链路，大幅提升项目交付效率；</li><li>具备前端组件化/工程化开发思维，擅长需求拆解与技术方案制定，可统筹开发进度，精准适配政企GIS类项目全链路需求。</li></ol><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><h3 id="前端-gis-开发" tabindex="-1">前端&amp; GIS 开发 <a class="header-anchor" href="#前端-gis-开发" aria-label="Permalink to &quot;前端&amp; GIS 开发&quot;">​</a></h3><ul><li>熟练掌握Vue2/Vue3+TS/Vite/ElementPlus全套技术栈，理解MVVM思想，擅长通用组件/业务模块封装，熟练掌握PC / 移动端响应式开发；</li><li>深耕GIS地图开发，熟练掌握Openlayer/Mapbox/高德二维地图，了解Cesium三维地图及GIS相关技术，能封装地图核心方法并实现个性化业务开发；</li><li>熟练掌握微信小程序原生、UniApp跨端开发，能完成从构建、开发到发布全流程；熟练掌握Flex布局、CSS3动画，可通过Less/Sass/Stylus高度还原设计稿；</li><li>熟练使用Git/SVN版本控制、Nginx部署，可在Windows/Linux搭建前后端开发环境；熟悉浏览器运行机制，掌握sessionStorage/indexedDB本地存储、WebSocket实时通信，解决大体积数据存储、实时推送等技术难点。</li></ul><h3 id="python-爬虫-数据处理" tabindex="-1">Python 爬虫&amp; 数据处理 <a class="header-anchor" href="#python-爬虫-数据处理" aria-label="Permalink to &quot;Python 爬虫&amp; 数据处理&quot;">​</a></h3><ul><li>熟练掌握Python基础语法，熟练使用Python做数据采集、清洗、处理、入库，可编写脚本实现CSV/Excel数据自动化计算、入库及文件生成；</li><li>具备高级爬虫实战能力，可完成补环境、瑞数反爬、Webpack逆向，熟练掌握AES/RSA加解密，能破解请求/响应加密接口获取批量数据；</li><li>熟练使用Python爬虫相关库，可将采集数据存入MySQL、PostgreSQL数据库(可集成PostGIS地理信息扩展)，完成GIS地理数据、业务数据的专业化存储与可视化前置处理，形成「采集-清洗-地理化存储-可视化」完整数据闭环；</li><li>了解Node.js，可使用Express/Koa开发简单接口，结合Nightmare/Puppeteer实现模拟浏览器请求的爬虫开发。</li></ul><h3 id="后端-ai-工具-其他能力" tabindex="-1">后端&amp; AI 工具&amp; 其他能力 <a class="header-anchor" href="#后端-ai-工具-其他能力" aria-label="Permalink to &quot;后端&amp; AI 工具&amp; 其他能力&quot;">​</a></h3><ul><li>熟练掌握Java基础，熟练使用若依框架完成增删改查接口开发，能独立完成小型模块前后端全栈开发；</li><li>熟练掌握MySQL、PostgreSQL数据库基础操作与设计，可在PostgreSQL中集成PostGIS地理信息扩展，实现GIS空间数据的存储、查询与关联分析，适配政企地理信息类项目数据需求；</li><li>熟练使用Cursor、通义灵码、Trae等主流AI编程工具，精通AI辅助代码生成、项目重构、调试优化、需求拆解等实操能力，将AI工具深度融入编码、调试、部署全流程，大幅提升开发效率与项目交付速度；</li><li>掌握前端工程化、组件化开发思想，具备需求拆解与落地能力，能将业务需求提炼为技术功能点，制定前端开发方案并统筹开发进度。</li></ul><h2 id="工作经历" tabindex="-1">工作经历 <a class="header-anchor" href="#工作经历" aria-label="Permalink to &quot;工作经历&quot;">​</a></h2><h3 id="中国移动设计院-web-前端开发-2024-04-至今" tabindex="-1">中国移动设计院 | Web 前端开发 | 2024.04 - 至今 <a class="header-anchor" href="#中国移动设计院-web-前端开发-2024-04-至今" aria-label="Permalink to &quot;中国移动设计院 | Web 前端开发 | 2024.04 - 至今&quot;">​</a></h3><p><strong>核心方向</strong>：政企数字化项目开发 | GIS 地图开发 | Python 高级爬虫 | AI 功能开发 | 若依框架后端开发 | GIS 数据存储</p><ol><li>负责无线网质量评估系统(政企核心项目)多模块开发：独立完成GIS模块全开发，基于Openlayer封装核心方法实现组件化调用，改造气泡窗支持Element-UI渲染，提升模块复用性；授权后通过Python高级爬虫破解加密接口，采集批量基站GIS与业务数据，存入PostgreSQL+PostGIS数据库，为基站修复提供多维度数据支撑；开发AI会话助手，支持语音/文字输入，可识别SQL请求并执行，动态生成表格/图表/地图标注；独立完成诉中管控模块前后端开发，开发专属接口，实现与微信机器人的定时任务数据实时同步，支撑政企诉中管控高效落地。</li><li>独立开发CSV数据自动化同步项目：编写Python脚本实现5张基表+4张固定表自动化计算、3张结果表批量入库PostgreSQL，一键完成数据处理、入库及Excel文件生成，将月度人工数据同步工作优化为自动化操作，大幅提升政企数据处理效率。</li><li>独立承接OMC服务器管理平台开发：承接100+台OMC服务器管理平台开发，独立完成需求拆解、前端全模块开发及开发进度统筹；打造核心管理模块，实现服务器状态表格可视化，开发可拖拽式多窗口交互功能，模拟文件夹层级管理逻辑，通过sessionStorage保证窗口信息刷新不丢失；基于WebSocket实现日志实时展示，采用indexedDB存储大体积日志并设计缓存清理机制；开发jar包批量上传、日志在线编辑功能，实现后端文件流解析-编辑-回传全流程，无需本地下载即可完成修改。</li><li>参与跨单位大屏协同开发项目：基于Vue3+TS负责指定模块组件化开发，保障组件的复用性与兼容性，配合团队完成大屏项目落地。</li></ol><h3 id="环亚数字经济研究院-web-前端开发-2021-09-2024-01" tabindex="-1">环亚数字经济研究院 | Web 前端开发 | 2021.09 - 2024.01 <a class="header-anchor" href="#环亚数字经济研究院-web-前端开发-2021-09-2024-01" aria-label="Permalink to &quot;环亚数字经济研究院 | Web 前端开发 | 2021.09 - 2024.01&quot;">​</a></h3><p><strong>核心方向</strong>：政企后台管理系统 | 大屏可视化 | Mapbox 地图开发 | UniApp 小程序开发</p><ol><li>商业云交投大脑二/三级看板(核心大屏项目)：基于Mapbox开发WGS84坐标系地图模块，封装通用地图组件，实现底图切换、点位标注、多省市地图切换、个性化气泡窗渲染，点击公司/点位可联动刷新数据图表，适配数字中心规范要求；</li><li>商业集团商铺管理系统：基于若依框架搭建前端架构，实现服务区平面图统一封装、高德地图多边形/点位联动渲染，开发大文件分片上传功能(基于vue-simple-uploader)并封装为通用文件管理页面，适配多业务类型文件上传；</li><li>高速驿网小程序：基于UniApp+u-view开发定制化小程序，完成从构建、开发到发布全流程，实现服务区及司机相关定制化功能；</li><li>浙商互联收银系统后台管理：基于Vue3+Vite+Pinia开发，封装通用表格组件，通过配置快速实现表格增删改查及样式统一，提升开发效率；</li><li>能源管控系统：基于Vite+Vue3+ElementPlus开发后台管理系统，熟练运用Vue3核心特性完成常规业务开发。</li></ol><h3 id="北京天天智慧智电科技有限公司-web-前端开发-2020-10-2021-07" tabindex="-1">北京天天智慧智电科技有限公司 | Web 前端开发 | 2020.10 - 2021.07 <a class="header-anchor" href="#北京天天智慧智电科技有限公司-web-前端开发-2020-10-2021-07" aria-label="Permalink to &quot;北京天天智慧智电科技有限公司 | Web 前端开发 | 2020.10 - 2021.07&quot;">​</a></h3><p><strong>核心方向</strong>：电力行业后台管理系统 | 数据驾驶舱 | Node.js 爬虫开发</p><ol><li>售电管理用户侧平台(大渡河)：基于AVUE开发合同/审批/系统管理模块，攻克合同模块复杂交互难点，实现多选项卡数据统一提交、异步接口轮询及进度条展示，封装富文本、树状结构筛选、文件上传等通用小工具；</li><li>售电管理用户侧平台(产品化)：负责数据驾驶舱开发，通过Proxy代理调用ES服务，封装Axios方法实现ES索引数据增删改查及图表生成；基于Node.js+Nightmare/Puppeteer开发爬虫，授权后采集电力公司数据并存入MySQL，为数据中台提供数据支撑。</li></ol><h3 id="杭州德慧信息技术有限公司-web-前端开发-技术负责人-2019-10-2020-09" tabindex="-1">杭州德慧信息技术有限公司 | Web 前端开发/技术负责人 | 2019.10 - 2020.09 <a class="header-anchor" href="#杭州德慧信息技术有限公司-web-前端开发-技术负责人-2019-10-2020-09" aria-label="Permalink to &quot;杭州德慧信息技术有限公司 | Web 前端开发/技术负责人 | 2019.10 - 2020.09&quot;">​</a></h3><p><strong>核心方向</strong>：GIS 三维可视化 | 大屏项目全流程开发 | 团队技术框架搭建与版本管理</p><ol><li>作为初创公司技术负责人，牵头搭建前端Vue全家桶技术框架，制定团队开发规范，统筹完成团队版本管理从Gitlab到SVN的切换，带领5人团队落地12个政企级GIS三维可视化大屏项目，全部按时按标交付，客户满意度100%。</li><li>基于Cesium引擎对火星科技平台进行二次开发，掌握三维模型基础原理及多格式转换与加载，实现模型单体化、视频投影等定制化功能；落地模型加载、标注、视点、智能巡更增删改查核心功能，实现点击模型联动加载关联业务数据的交互效果。</li><li>打通三维可视化平台与IOT设备数据链路，实现设备数据实时采集、统计图可视化展示，深度融合三维模型与业务数据落地大屏可视化需求，完成杭州德慧SE/Gsp引擎三维可视化平台、智慧楼宇/园区/社区应急指挥平台、中国电视台大屏、大旺化工厂三维可视化平台等标杆项目，主导开发安卓端OA系统，适配项目全流程管理需求。</li></ol><h3 id="其他工作经历-核心能力提炼" tabindex="-1">其他工作经历(核心能力提炼) <a class="header-anchor" href="#其他工作经历-核心能力提炼" aria-label="Permalink to &quot;其他工作经历(核心能力提炼)&quot;">​</a></h3><ol><li>杭州栖木科技有限公司(2018.12-2019.06)：基于Vue2开发后台管理系统/移动端项目，封装Axios、实现富文本/国际化，解决UI框架样式穿透问题，搭建前端开发环境模板；</li><li>浙江不动谷信息科技有限公司(2016.10-2018.12)：独立开发维护电商类微信公众号/小程序，技术栈涵盖jQuery/Vue/微信小程序原生；</li><li>杭州和木电子商务有限公司(2015.10-2016.10)：独立开发跨境电商平台(PC / 移动端/公众号)，实现商品展示、购物车、订单、物流等核心电商功能；</li><li>浙江七巧板信息科技有限公司(2015.04-2015.10)：开发公安系统基础警务平台，适配IE8+浏览器，完成切图、前端开发、浏览器兼容及接口联调。</li></ol><h2 id="个人评价" tabindex="-1">个人评价 <a class="header-anchor" href="#个人评价" aria-label="Permalink to &quot;个人评价&quot;">​</a></h2><p>8年政企GIS/数据可视化前端开发实战经验，精通GIS二/三维开发、Python全流程数据处理、前端全栈技术及Java若依框架后端开发，可独立完成政企级GIS / 数据可视化项目从需求拆解、技术方案制定到全流程开发落地的全链路工作；熟练运用Cursor、通义灵码等AI工具融入开发全流程，大幅提升项目交付效率与质量。</p><p>熟悉政务大数据开发规范与政企项目落地流程，具备优秀的需求拆解、团队统筹与项目管理能力，拥有丰富的政企项目实战与团队协作经验。未来将持续深化GIS与数据融合的技术能力，结合AI工具与全栈思维，不断提升复杂业务场景的技术落地与优化能力，为企业数字化建设提供贴合需求的技术支撑与解决方案。</p>',30)]))}const p=a(o,[["render",r]]);export{m as __pageData,p as default};
